	@Test
	void customSailDelegatesReceiveNormalizedAlgebraAndKeepTheirEvaluator() {
		AtomicInteger evaluations = new AtomicInteger();
		Sail sail = new SailWrapper(new MemoryStore()) {
			@Override
			public SailConnection getConnection() {
				return new SailConnectionWrapper(super.getConnection()) {
					@Override
					public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
							Value object, boolean includeInferred, Resource... contexts) {
						throw new AssertionError("Parser query execution must retain this Sail's evaluator");
					}

					@Override
					public CloseableIteration<? extends BindingSet> evaluate(
							TupleExpr expression, Dataset dataset, BindingSet bindings, boolean includeInferred) {
						evaluations.incrementAndGet();
						assertTrue(RdfParserQuerySupport.isParserQuery(expression));
						AtomicInteger tupleCalls = new AtomicInteger();
						expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
							@Override
							public void meetOther(QueryModelNode node) {
								if (node instanceof TupleFunctionCall call
										&& RdfParseVocabulary.TURTLE.stringValue().equals(call.getURI())) {
									tupleCalls.incrementAndGet();
								}
								super.meetOther(node);
							}
						});
						assertEquals(1, tupleCalls.get());
						return super.evaluate(expression, dataset, bindings, includeInferred);
					}
				};
			}
		};
		SailRepository repository = new SailRepository(sail);
		repository.init();
		try (var connection = repository.getConnection()) {
			assertEquals(1,
					select(connection, PREFIX + "SELECT ?name WHERE { " + BODIES.get(0) + " }", DOCUMENT).size());
			assertEquals(1, evaluations.get());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void transformingSailStacksRetainTheirInferenceSemantics() {
		SailRepository repository = new SailRepository(new SchemaCachingRDFSInferencer(new MemoryStore()));
		repository.init();
		try (var connection = repository.getConnection()) {
			connection.add(VF.createIRI("urn:rawName"), RDFS.SUBPROPERTYOF, VF.createIRI("urn:name"));
			connection.add(VF.createIRI("urn:person"), VF.createIRI("urn:rawName"), VF.createLiteral("Alice"));
			long before = connection.size();
			var rows = select(connection,
					PREFIX + "SELECT ?name WHERE { ?doc parse:turtle (?s <urn:related> ?person) . "
							+ "?person <urn:name> ?name }",
					"<urn:source> <urn:related> <urn:person> .");
			assertEquals(1, rows.size());
			assertEquals(VF.createLiteral("Alice"), rows.get(0).getValue("name"));
			assertEquals(before, connection.size());
			assertFalse(connection.hasStatement(VF.createIRI("urn:source"), VF.createIRI("urn:related"),
					VF.createIRI("urn:person"), false));
		} finally {
			repository.shutDown();
		}
	}

	private static boolean hasOneResult(GenericPlanNode node) {
		return Long.valueOf(1).equals(node.getResultSizeActual()) || node.getPlans()
				.stream()
				.anyMatch(RdfParserStandardIntegrationTest::hasOneResult);
	}

	private static List<BindingSet> select(SailRepositoryConnection connection, String queryText, String document) {
		var query = connection.prepareTupleQuery(queryText);
		query.setBinding("doc", VF.createLiteral(document));
		List<BindingSet> rows = new ArrayList<>();
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}
